#!/usr/bin/env python3
"""Embed the upstream MIT-licensed FidelityFX FSR1 shader headers for GL runtime compilation."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
source = root / "third_party/fidelityfx"
out = root / "src/render/fsr1_embedded.hpp"
items = [("kFfxA", source / "ffx_a.h"), ("kFfxFsr1", source / "ffx_fsr1.h"), ("kEasu", root / "src/render/shaders/fsr1_easu.frag"), ("kRcas", root / "src/render/shaders/fsr1_rcas.frag")]
parts = [
    "// Generated by tools/embed_fsr1.py. Do not edit by hand.\n",
    "// AMD FidelityFX FSR 1, MIT license: see third_party/fidelityfx/license.txt.\n",
    "#pragma once\nnamespace xyo::fsr_embedded {\n",
]
for symbol, name in items:
    body = name.read_text(encoding="utf-8")
    assert ")FSR1_GLSL\";" not in body
    parts.append(f"inline constexpr char {symbol}[] = R\"FSR1_GLSL({body})FSR1_GLSL\";\n")
parts.append("} // namespace xyo::fsr_embedded\n")
out.write_text("".join(parts), encoding="utf-8")
print(out, out.stat().st_size)
